examples.template:
MonarchEventChip({{event.title}}, time: {{chipTime}}, color: Color(red: 47 / 255.0, green: 125 / 255.0, blue: 109 / 255.0), variant: .bar) { isShown = true }
    .popover(isPresented: $isShown) {
        MonarchEventPopover(
            {{event.title}},
            subtitle: {{event.detail}},
            start: {{event.start|date}},
            end: {{event.end|date}},
            color: Color(red: 47 / 255.0, green: 125 / 255.0, blue: 109 / 255.0),
            status: {{event.status|case}},
            details: [
                MonarchEventPopoverDetail({{details.0.label}}, value: {{details.0.value}}),
                MonarchEventPopoverDetail({{details.1.label}}, value: {{details.1.value}}),
            ],
            timeZone: TimeZone(identifier: {{timeZone}})
        ) {
            MonarchButton({{actions.0}}, variant: .secondary, size: .sm) { isShown = false }
            MonarchButton({{actions.1}}, variant: .dangerSubtle, size: .sm) { isShown = false }
        }
        .presentationCompactAdaptation(.popover)
        .presentationBackground(theme.colors.bgRaised)
        .environment(\.locale, Locale(identifier: {{locale}}))
    }

examples.code:
MonarchEventChip("Sam Lee", time: "09:30", color: Color(red: 47 / 255.0, green: 125 / 255.0, blue: 109 / 255.0), variant: .bar) { isShown = true }
    .popover(isPresented: $isShown) {
        MonarchEventPopover(
            "Sam Lee",
            subtitle: "Consultation",
            start: Date(timeIntervalSince1970: 1_793_784_600),
            end: Date(timeIntervalSince1970: 1_793_787_300),
            color: Color(red: 47 / 255.0, green: 125 / 255.0, blue: 109 / 255.0),
            status: .confirmed,
            details: [
                MonarchEventPopoverDetail("Hosts", value: "Alex Kim"),
                MonarchEventPopoverDetail("Reference", value: "AB12CD"),
