            timeZone: TimeZone(identifier: "Europe/London")
        ) {
            MonarchButton("Open", variant: .secondary, size: .sm) { isShown = false }
            MonarchButton("Cancel booking", variant: .dangerSubtle, size: .sm) { isShown = false }
        }
        .presentationCompactAdaptation(.popover)
        .presentationBackground(theme.colors.bgRaised)
        .environment(\.locale, Locale(identifier: "en-GB"))
    }
